define(['knockout','uiComponent','Magento_PaymentServicesPaypal/js/helpers/is-fastlane-available','Magento_PaymentServicesPaypal/js/view/payment/fastlane'],function(ko,Component,isFastlaneAvailable,fastlaneModel){'use strict';return Component.extend({profileData:null,defaults:{template:'Magento_PaymentServicesPaypal/form/element/powered-by'},initialize:function(config){this._super(config);this.id=config.id;this.profileData=fastlaneModel.profileData;this.isVisible=ko.observable(false);this.profileData.subscribe(this.renderWatermark.bind(this));return this;},isEmailWatermarkEnabled:function(){return this.id==='paypal-fastlane-email-watermark'&&window.checkoutConfig.payment.payment_services_paypal_fastlane.messaging;},isShippingWatermarkEnabled:function(){return this.id!=='paypal-fastlane-email-watermark'&&!!this.profileData();},shouldRenderWatermark:async function(){if(!isFastlaneAvailable()){return false;}
await fastlaneModel.setup();const shouldRender=this.isEmailWatermarkEnabled()||this.isShippingWatermarkEnabled();this.isVisible(shouldRender);},renderWatermark:async function(){await this.shouldRenderWatermark();if(this.isVisible()){fastlaneModel.renderFastlaneWatermarkComponent(`#${this.id}`);}}});});